function calculateEndDate(requiredSendingDays) {
  if (requiredSendingDays === null) {
    return null;
  }

  const enabledDayCount = Object.values(enabledDays).filter(Boolean).length;
  if (enabledDayCount === 0) {
    return null;
  }

  const zonedNow = getZonedDateParts(new Date(), timezone);
  const cursor = new Date(
    Date.UTC(zonedNow.year, zonedNow.month - 1, zonedNow.day)
  );

  if (requiredSendingDays === 0) {
    return formatDate(cursor);
  }

  const currentMinutes = zonedNow.hour * 60 + zonedNow.minute;
  const scheduleEndMinutes = parseTimeToMinutes(schedule.end_time);
  const todayName = dayNames[cursor.getUTCDay()];

  const canStillSendToday =
    enabledDays[todayName] &&
    (scheduleEndMinutes === null || currentMinutes < scheduleEndMinutes);

  let countedSendingDays = canStillSendToday ? 1 : 0;

  while (countedSendingDays < requiredSendingDays) {
    cursor.setUTCDate(cursor.getUTCDate() + 1);

    if (enabledDays[dayNames[cursor.getUTCDay()]]) {
      countedSendingDays++;
    }
  }

  return formatDate(cursor);
}

